import json,urllib.request,sys
URL="http://127.0.0.1:33975/mcp/70aa32cc4e58b63f9a7dcb31ec46da37"
def raw(payload):
    req=urllib.request.Request(URL, data=json.dumps(payload).encode(), headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream"})
    r=urllib.request.urlopen(req, timeout=60)
    return r.read().decode()
def parse(body):
    # SSE or json
    if body.lstrip().startswith("{"):
        return json.loads(body)
    for line in body.splitlines():
        if line.startswith("data:"):
            return json.loads(line[5:].strip())
    return None
def rpc(method, params=None, _id=1):
    return parse(raw({"jsonrpc":"2.0","id":_id,"method":method,"params":params or {}}))
def notify(method, params=None):
    try:
        raw({"jsonrpc":"2.0","method":method,"params":params or {}})
    except Exception as e:
        pass
if __name__=="__main__":
    rpc("initialize",{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"c","version":"1"}})
    notify("notifications/initialized")
    cmd=sys.argv[1] if len(sys.argv)>1 else "list"
    if cmd=="list":
        res=rpc("tools/list",{},2)
        for t in res["result"]["tools"]:
            print("###",t["name"])
            print(t.get("description","")[:600])
            print(json.dumps(t.get("inputSchema",{}))[:900])
            print()
    else:
        name=sys.argv[1]; args=json.loads(sys.argv[2]) if len(sys.argv)>2 else {}
        res=rpc("tools/call",{"name":name,"arguments":args},2)
        print(json.dumps(res,indent=2)[:20000])
